<?php
declare(strict_types=1);
namespace CommunityHub;
final class Automation {
 public static function condition(array $c,array $context):bool{$value=$context;foreach(explode('.',$c['field_name']) as $p)$value=is_array($value)?($value[$p]??null):null;$a=is_bool($value)?($value?'true':'false'):(is_scalar($value)?(string)$value:'');$e=(string)($c['comparison_value']??'');$list=array_map('trim',explode(',',$e));return match($c['operator_name']){'equals'=>$a===$e,'not_equals'=>$a!==$e,'contains'=>str_contains($a,$e),'not_contains'=>!str_contains($a,$e),'in'=>in_array($a,$list,true),'not_in'=>!in_array($a,$list,true),'is_empty'=>$a==='','is_not_empty'=>$a!=='',default=>false};}
 public static function action(array $action,array $context,?int $actor):array{$c=json_decode($action['action_config_json']??'{}',true)?:[];$user=$context['subject_user_id']??$context['user_id']??$c['user_id']??null;switch($action['action_type']){case 'create_notification':if(!$user)throw new HttpError('Notification requires a subject user.');App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$user,$c['title']??'CommunityHub Flow',$c['message']??'An automated workflow was completed.',$c['url']??null]);break;case 'set_member_status':if(!$user||empty($c['status']))throw new HttpError('Member status requires user and status.');App::query('UPDATE users SET member_status=? WHERE id=?',[$c['status'],$user]);break;case 'set_recruit_stage':if(!$user||empty($c['stage']))throw new HttpError('Recruit stage requires user and stage.');App::query('INSERT INTO recruit_pipeline(user_id,department_id,stage,notes,changed_by) SELECT id,department_id,?,?,? FROM users WHERE id=?',[$c['stage'],$c['notes']??'CommunityHub Flow',$actor,$user]);break;case 'write_staff_note':if(!$user)throw new HttpError('Staff note requires a subject user.');App::query('INSERT INTO staff_notes(user_id,note_type,note_text,created_by) VALUES(?,?,?,?)',[$user,$c['note_type']??'general',$c['note_text']??'CommunityHub Flow action',$actor]);break;case 'write_audit_log':App::audit($actor,$c['action']??'automation.flow',$context['entity_type']??'automation',(int)($context['entity_id']??0),$context);break;default:throw new HttpError('Unsupported automation action.');}return ['user_id'=>$user,'logged'=>true];}
 public static function emit(string $trigger,array $context=[],?int $actor=null,?int $flowId=null):array{$flows=App::rows('SELECT * FROM automation_flows WHERE is_enabled=1 AND trigger_type=?'.($flowId?' AND id=?':'').' ORDER BY id',$flowId?[$trigger,$flowId]:[$trigger]);$results=[];foreach($flows as $f){$conditions=App::rows('SELECT * FROM automation_conditions WHERE flow_id=? ORDER BY sort_order,id',[$f['id']]);$passes=!array_filter($conditions,fn($c)=>!self::condition($c,$context));$run=App::insert('INSERT INTO automation_runs(flow_id,trigger_type,entity_type,entity_id,subject_user_id,status,context_json) VALUES(?,?,?,?,?,?,?)',[$f['id'],$trigger,$context['entity_type']??null,$context['entity_id']??null,$context['subject_user_id']??$context['user_id']??null,$passes?'running':'skipped',json_encode($context,JSON_THROW_ON_ERROR)]);$status=$passes?'success':'skipped';$error=null;if($passes)try{foreach(App::rows('SELECT * FROM automation_actions WHERE flow_id=? ORDER BY sort_order,id',[$f['id']]) as $a){try{$result=self::action($a,$context,$actor);App::query("INSERT INTO automation_action_runs(run_id,action_id,action_type,status,result_json) VALUES(?,?,?,'success',?)",[$run,$a['id'],$a['action_type'],json_encode($result,JSON_THROW_ON_ERROR)]);}catch(\Throwable $e){App::query("INSERT INTO automation_action_runs(run_id,action_id,action_type,status,error_message) VALUES(?,?,?,'failed',?)",[$run,$a['id'],$a['action_type'],mb_substr($e->getMessage(),0,4000)]);throw $e;}}}catch(\Throwable $e){$status='failed';$error=mb_substr($e->getMessage(),0,4000);}App::query('UPDATE automation_runs SET status=?,error_message=?,finished_at=NOW() WHERE id=?',[$status,$error,$run]);$results[]=['flow_id'=>(int)$f['id'],'status'=>$status,'error'=>$error];}return $results;}
}
